    [4504]={name="Dwarven Guard Cloak",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'The Thandol Span' - pick it over the other choices. In Wetlands.",zone="Wetlands",questName="The Thandol Span",lore="Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."},
    [4507]={name="Pit Fighter's Shield",quality=3,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'Trol'kalar' - pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Trol'kalar",lore="The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."},
    [4508]={name="Blood-tinged Armor",quality=3,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'Trol'kalar' - pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Trol'kalar",lore="The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."},
    [4511]={name="Black Water Hammer",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Deep Sea Salvage'. In Arathi Highlands.",zone="Arathi Highlands",questName="Deep Sea Salvage",lore="O'Breen led the ships into the cove. We were certain this is where the treasure could be found. The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower."},
    [4535]={name="Ironforge Memorial Ring",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'A King's Tribute'. In Ironforge.",zone="Ironforge",questName="A King's Tribute",lore="Such a shame the land is in such shambles. But the Memorial came out quite well!"},
