    [9651]={name="Gryphon Rider's Stormhammer",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",proc="Chance on hit: Blasts a target for 91 to 125 Nature damage."},
    [9664]={name="Sentinel's Guard",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Delivering the Relic' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Delivering the Relic",lore="If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."},
    [9684]={name="Force of the Hippogryph",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Spirit' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Weapons of Spirit",lore="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."},
