    [11858]={name="Battlehard Cape",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'A Grim Discovery' - pick it over the other choices. In Feralas.",zone="Feralas",questName="A Grim Discovery",lore="What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."},
    [11862]={name="White Bone Band",quality=2,ilvl=52,sourceType="quest_reward",instructions="Reward from the quest 'Bone-Bladed Weapons' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Bone-Bladed Weapons",lore="In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."},
    [11905]={name="Linken's Boomerang",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'It's Dangerous to Go Alone'. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero...",proc="Use: Flings a magical boomerang towards target enemy dealing 113 to 187 damage and has a chance to stun or disarm them. (3 Min Cooldown)"},
    [11910]={name="Bejeweled Legguards",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'A Little Help From My Friends' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="A Little Help From My Friends",lore="Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."},
    [11915]={name="Shizzle's Drizzle Blocker",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Shizzle's Flyer' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="Shizzle's Flyer",lore="I'm making a flying machine! I got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death."},
