    [15451]={name="Gargoyle Leggings",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Power to Destroy...' - pick it over the other choices. In Ragefire Chasm.",zone="Ragefire Chasm",questName="The Power to Destroy...",lore="Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."},
    [15459]={name="Grimtoll Wristguards",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Grimtotem Spying' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Grimtotem Spying",lore="you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks."},
