    [15689]={name="Trader's Ring",quality=2,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Bodyguard for Hire'. In Desolace.",zone="Desolace",questName="Bodyguard for Hire",lore="Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."},
    [15690]={name="Kodobone Necklace",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Bone Collector'. In Desolace.",zone="Desolace",questName="Bone Collector",lore="We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."},
    [15695]={name="Studded Ring Shield",quality=2,ilvl=38,sourceType="quest_reward",instructions="Reward from the quest 'Gizelton Caravan' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Gizelton Caravan",lore="You look like a capable. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!"},
    [15698]={name="Wrangling Spaulders",quality=2,ilvl=38,sourceType="quest_reward",instructions="Reward from the quest 'Kodo Roundup' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Kodo Roundup",lore="Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me."},
    [15703]={name="Chemist's Smock",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Melding of Influences' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Melding of Influences",lore="Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."},
    [15704]={name="Hunter's Insignia Medal",quality=2,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Past Endeavors'. In Winterspring.",zone="Winterspring",questName="Past Endeavors",lore="Before you spoke to me, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a, and I now know these things to be the truth."},
    [15789]={name="Deep River Cloak",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'Strange Sources'. In Winterspring.",zone="Winterspring",questName="Strange Sources",lore="To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."},
    [15799]={name="Heroic Commendation Medal",quality=2,ilvl=58,sourceType="quest_reward",instructions="Reward from the quest 'Mission Accomplished!'. In Western Plaguelands.",zone="Western Plaguelands",questName="Mission Accomplished!"},
    [15806]={name="Mirah's Song",quality=3,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Kirtonos the Herald' - pick it over the other choices. In Scholomance.",zone="Scholomance",questName="Kirtonos the Herald",lore="Mirah Chandler's song, given for finishing a chain of favours in the Barrens -- the reward players remember long after they forget the errands."},
