    [21126]={name="Death's Sting",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21134]={name="Dark Edge of Insanity",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Chance on hit: Disorients the target, causing it to wander aimlessly for up to 3 sec."},
    [21184]={name="Deeprock Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21242]={name="Blessed Qiraji War Axe",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21269]={name="Blessed Qiraji Bulwark",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21316]={name="Leggings of the Ursa",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Deadwood of the North' - pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21329]={name="Conqueror's Crown",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Crown'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Crown",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21330]={name="Conqueror's Spaulders",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Spaulders'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Spaulders",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21331]={name="Conqueror's Breastplate",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Breastplate'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Breastplate",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21332]={name="Conqueror's Legguards",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Legguards'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Legguards",lore="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."},
    [21333]={name="Conqueror's Greaves",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Greaves'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Greaves",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21394]={name="Drape of Unyielding Strength",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Drape of Unyielding Strength'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Drape of Unyielding Strength",lore="I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."},
    [21485]={name="Buru's Skull Fragment",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Buru the Gorger in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Buru the Gorger"},
